tasks.loopCondition:
// fetch_dependency_pages loop condition: returns true to fetch another page.
// Keep going while deps.dev returns a page token. The cap of 50 pages (100 versions each)
// matches the 5,000-request limit and stops a runaway loop.
function shouldFetchAnotherPage() {
  const lastPage = $.version_batch_ref || {};
  if (!lastPage.nextPageToken) {
    return false;
  }
  return $.dependency_pages_ref.iteration < 50;
}

shouldFetchAnotherPage();

// lookup_dependency_advisories loop condition: returns true to look up another dependency.
// One OSV lookup per vulnerable dependency. Counting iterations also stops the loop correctly
// if the server treats this as a plain loop instead of a list loop.
function shouldLookUpAnother() {
  return $.dependency_advisories_ref.iteration < $.items.length;
}

shouldLookUpAnother();
